internal final class FTDQueryVSSelect
{
	//Ejercicio, query vs select: vamos a mostrar en un info, el id y nombre de los libros, 
	//y el nombre y apellido de los autores de los libros de fantasía.

}

Method.Source:
	public void selectExample()
    {
        FTDAuthorTable authorTable;
        FTDBookTable bookTable;

        while select FirstName, LastName from authorTable
            join Id, Name from bookTable
            where authorTable.RecId == bookTable.Author
            && bookTable.Genre == FTDGenreEnum::Fantasy
        {
            info(strFmt('%1 %2 - %3 %4', 
                bookTable.Id, 
                bookTable.Name, 
                authorTable.FirstName, 
                authorTable.LastName));
        }
    }

	public void reuseExistingQuery()
    {
        Query ftdBookAuthorFantasyQuery = new Query(queryStr(ftdBookAuthorFantasyQuery));

        this.runQuery(ftdBookAuthorFantasyQuery);
    }

public void buildQueryFromCode()
{
    Query ftdBookAuthorFantasyQuery = new Query();

    QueryBuildDataSource qbdsAuthorTable = ftdBookAuthorFantasyQuery.addDataSource(tableNum(FTDAuthorTable));
    QueryBuildDataSource qbdsBookTable = qbdsAuthorTable.addDataSource(tableNum(FTDBookTable));

    qbdsBookTable.joinMode(JoinMode::InnerJoin);
    //qbdsBookTable.relations(true);

    qbdsBookTable.addLink(fieldNum(FTDAuthorTable, RecId), 
        fieldNum(FTDBookTable, Author), 
        qbdsAuthorTable.name());

    QueryBuildRange qbrGenre = qbdsBookTable.addRange(fieldNum(FTDBookTable, Genre));
    qbrGenre.value(queryValue(FTDGenreEnum::Fantasy));
    //si queremos anadir un valor nuevo a un rango existente
    qbrGenre.value(queryRangeConcat(qbrGenre.value(), queryValue(FTDGenreEnum::HistoryNovel)));

    this.runQuery(ftdBookAuthorFantasyQuery);
}

public void runQuery(Query _q)
{
    QueryRun qr = new QueryRun(_q);

    while(qr.next())
    {
        FTDBookTable bookTable = qr.get(tableNum(FTDBookTable));
        FTDAuthorTable authorTable = qr.get(tableNum(FTDAuthorTable));

        info(strFmt('%1 %2 - %3 %4',
            bookTable.Id,
            bookTable.Name,
            authorTable.FirstName,
            authorTable.LastName));
    }
}
